[{"order":1,"type":"heading","text":"Runtime Validation Integration: Zod, io-ts, and TypeBox in TypeScript"},{"order":2,"type":"paragraph","text":"TypeScript provides static type checking at compile time, but it disappears at runtime. When dealing with external data sources like API responses, user inputs, or database queries, compile-time safety is not enough. Runtime validation libraries ensure that the data flowing into your application matches your TypeScript types."},{"order":3,"type":"subheading","text":"Introduction to Zod"},{"order":4,"type":"paragraph","text":"Zod is a TypeScript-first schema declaration and validation library. It is designed to be developer-friendly, allowing you to declare a validator once and automatically infer its TypeScript type."},{"order":5,"type":"code","text":"import { z } from 'zod';

const UserSchema = z.object({
  id: z.number(),
  name: z.string(),
  email: z.string().email(),
  role: z.enum(['admin', 'user'])
});

type User = z.infer<typeof UserSchema>;

function processUserData(data: unknown) {
  const result = UserSchema.safeParse(data);
  if (!result.success) {
    console.error(result.error.format());
    throw new Error('Invalid user data');
  }
  const validUser: User = result.data;
  console.log("Processing user:", validUser.name);
}"},{"order":6,"type":"subheading","text":"Introduction to io-ts"},{"order":7,"type":"paragraph","text":"io-ts is a runtime type system for TypeScript heavily inspired by Haskell. It uses functional programming concepts and works exceptionally well if your codebase relies heavily on fp-ts."},{"order":8,"type":"code","text":"import * as t from 'io-ts';
import { isLeft } from 'fp-ts/lib/Either';
import { PathReporter } from 'io-ts/lib/PathReporter';

const UserCodec = t.type({
  id: t.number,
  name: t.string,
  email: t.string,
});

type User = t.TypeOf<typeof UserCodec>;

function validateWithIoTs(data: unknown) {
  const decoded = UserCodec.decode(data);
  if (isLeft(decoded)) {
    console.error(PathReporter.report(decoded));
    throw new Error('Validation failed');
  }
  const user: User = decoded.right;
  return user;
}"},{"order":9,"type":"subheading","text":"Introduction to TypeBox"},{"order":10,"type":"paragraph","text":"TypeBox allows you to create JSON Schema objects with static type inference. It is optimized for extreme performance and integrates seamlessly with fast JSON stringifiers and validators like Ajv."},{"order":11,"type":"code","text":"import { Type, Static } from '@sinclair/typebox';
import { TypeCompiler } from '@sinclair/typebox/compiler';

const UserType = Type.Object({
  id: Type.Number(),
  name: Type.String(),
  tags: Type.Array(Type.String())
});

type User = Static<typeof UserType>;

const Check = TypeCompiler.Compile(UserType);

function validateWithTypeBox(data: unknown) {
  if (!Check.Check(data)) {
    const errors = [...Check.Errors(data)];
    console.error(errors);
    throw new Error('TypeBox validation error');
  }
  const user: User = data;
  return user;
}"},{"order":12,"type":"subheading","text":"Comparing the Libraries"},{"order":13,"type":"bullet_point","text":"Zod: Best-in-class developer experience, highly expressive, chained API, very popular in modern full-stack web applications."},{"order":14,"type":"bullet_point","text":"io-ts: Ideal for functional programming enthusiasts who want strict type-safety guarantees paired with fp-ts."},{"order":15,"type":"bullet_point","text":"TypeBox: Best for high-performance microservices, native JSON Schema generation, and tight integration with validation engines like Ajv."},{"order":16,"type":"subheading","text":"Conclusion"},{"order":17,"type":"paragraph","text":"Integrating runtime validation ensures that edge cases, malformed API payloads, and unexpected user inputs are caught gracefully. Choose Zod for rapid feature development, io-ts for functional architectures, and TypeBox for raw performance and JSON Schema compatibility."}]
